async function run(client) {
  const r = await client.coins.marketChart.get('{{coin}}', { vs_currency: '{{vs}}', days: '{{days}}' });
  const caps = new Map(r.market_caps.map(([t, v]) => [t, v]));
  const vols = new Map(r.total_volumes.map(([t, v]) => [t, v]));
  return { crypto: '{{coin}}', devise: '{{vs|upper}}', observe_a: new Date().toISOString(),
    points: r.prices.map(([t, p]) => ({ horodatage: new Date(t).toISOString(), prix_{{vs}}: p, capitalisation_{{vs}}: caps.get(t) ?? null, volume_{{vs}}: vols.get(t) ?? null })) };
}

async function run(client) {
  const rows = await client.coins.markets.get({ vs_currency: '{{vs}}', order: 'market_cap_desc', per_page: {{n}}, page: 1, price_change_percentage: '24h,7d'{{#coin}}, ids: '{{coin}}'{{/coin}} });
  return { devise: '{{vs|upper}}', observe_a: new Date().toISOString(),
    cryptos: rows.map((c) => ({ id: c.id, symbole: String(c.symbol).toUpperCase(), nom: c.name, prix_{{vs}}: c.current_price, capitalisation_{{vs}}: c.market_cap, volume_24h_{{vs}}: c.total_volume, variation_24h_pct: c.price_change_percentage_24h, variation_7d_pct: c.price_change_percentage_7d_in_currency ?? null, rang: c.market_cap_rank, maj_le: c.last_updated })) };
}
